import json

def solve():
    houses = [{'House': i+1, 'Name': None, 'vacation': None, 'child': None, 'nationality': None} for i in range(5)]
    names = ['Alice', 'Bob', 'Arnold', 'Eric', 'Peter']
    vacations = ['cruise', 'city', 'camping', 'beach', 'mountain']
    children = ['Bella', 'Samantha', 'Fred', 'Meredith', 'Timothy']
    nationalities = ['dane', 'norwegian', 'brit', 'german', 'swede']

    # Used sets for all-different constraints
    used = {
        'Name': set(),
        'vacation': set(),
        'child': set(),
        'nationality': set()
    }

    # Pre-assignments from clues
    # 6. The person who likes going on cruises is in the first house.
    houses[0]['vacation'] = 'cruise'
    used['vacation'].add('cruise')

    # 7. The person's child is named Meredith is in the fourth house.
    houses[3]['child'] = 'Meredith'
    used['child'].add('Meredith')

    # 12. The Dane is in the fifth house.
    houses[4]['nationality'] = 'dane'
    used['nationality'].add('dane')

    attrs = ['Name', 'vacation', 'child', 'nationality']

    def value_used_elsewhere(attr, value, idx):
        for j in range(5):
            if j == idx:
                continue
            if houses[j][attr] == value:
                return True
        return False

    def find_index(attr, value):
        for i in range(5):
            if houses[i][attr] == value:
                return i
        return None

    def consistent():
        # All-different implicit via used sets; but also validate constraints.

        # 6. house 1 vacation cruise
        if houses[0]['vacation'] is not None and houses[0]['vacation'] != 'cruise':
            return False

        # 7. house 4 child Meredith
        if houses[3]['child'] is not None and houses[3]['child'] != 'Meredith':
            return False

        # 12. house 5 nationality dane
        if houses[4]['nationality'] is not None and houses[4]['nationality'] != 'dane':
            return False

        # 1. The Norwegian is Peter.
        for i in range(5):
            n = houses[i]['Name']
            nat = houses[i]['nationality']
            vac = houses[i]['vacation']
            ch = houses[i]['child']

            # Norwegian <-> Peter
            if nat == 'norwegian' and n is not None and n != 'Peter':
                return False
            if n == 'Peter' and nat is not None and nat != 'norwegian':
                return False
            if n == 'Peter' and value_used_elsewhere('nationality', 'norwegian', i):
                return False
            if nat == 'norwegian' and value_used_elsewhere('Name', 'Peter', i):
                return False

            # 5. Alice is the British person.
            if nat == 'brit' and n is not None and n != 'Alice':
                return False
            if n == 'Alice' and nat is not None and nat != 'brit':
                return False
            if n == 'Alice' and value_used_elsewhere('nationality', 'brit', i):
                return False
            if nat == 'brit' and value_used_elsewhere('Name', 'Alice', i):
                return False

            # 11. Bob is the person who enjoys camping trips.
            if vac == 'camping' and n is not None and n != 'Bob':
                return False
            if n == 'Bob' and vac is not None and vac != 'camping':
                return False
            if n == 'Bob' and value_used_elsewhere('vacation', 'camping', i):
                return False
            if vac == 'camping' and value_used_elsewhere('Name', 'Bob', i):
                return False

            # 2. The Swedish person has child Bella.
            if nat == 'swede' and ch is not None and ch != 'Bella':
                return False
            if ch == 'Bella' and nat is not None and nat != 'swede':
                return False
            if ch == 'Bella' and value_used_elsewhere('nationality', 'swede', i):
                return False
            if nat == 'swede' and value_used_elsewhere('child', 'Bella', i):
                return False

            # 3. beach directly left of Samantha.
            # If Samantha at i, then i>0 and vacation at i-1 is beach.
            if ch == 'Samantha':
                if i == 0:
                    return False
                left_v = houses[i-1]['vacation']
                if left_v is not None and left_v != 'beach':
                    return False
                # If beach is assigned elsewhere not at i-1 -> impossible
                bidx = find_index('vacation', 'beach')
                if bidx is not None and bidx != i-1:
                    return False
            # If beach at i, then i<4 and child at i+1 is Samantha.
            if vac == 'beach':
                if i == 4:
                    return False
                right_c = houses[i+1]['child']
                if right_c is not None and right_c != 'Samantha':
                    return False
                # If Samantha is assigned elsewhere not at i+1 -> impossible
                sidx = find_index('child', 'Samantha')
                if sidx is not None and sidx != i+1:
                    return False

            # 4. Bella is not in the second house.
            if i == 1 and ch == 'Bella':
                return False

            # 8. Eric is not in the fifth house.
            if i == 4 and n == 'Eric':
                return False

            # 13. Camping is not in the fifth house.
            if i == 4 and vac == 'camping':
                return False

        # 9. The Swedish person is somewhere to the right of the Norwegian.
        idx_nor = find_index('nationality', 'norwegian')
        idx_swe = find_index('nationality', 'swede')
        if idx_nor is not None and idx_swe is not None:
            if not (idx_swe > idx_nor):
                return False
        if idx_nor is not None and idx_nor == 4:
            return False  # No place to the right for Swede

        # Additional pruning using name Peter if available
        idx_peter = find_index('Name', 'Peter')
        if idx_peter is not None and idx_swe is not None:
            if not (idx_swe > idx_peter):
                return False

        # 10. One house between Fred and city.
        idx_fred = find_index('child', 'Fred')
        idx_city = find_index('vacation', 'city')
        if idx_fred is not None and idx_city is not None:
            if abs(idx_fred - idx_city) != 2:
                return False
        else:
            # If one is assigned, ensure possibility remains
            if idx_fred is not None and idx_city is None:
                possible = []
                for pos in [idx_fred - 2, idx_fred + 2]:
                    if 0 <= pos < 5:
                        v = houses[pos]['vacation']
                        if v is None or v == 'city':
                            possible.append(pos)
                if not possible:
                    return False
                # Also if 'city' assigned elsewhere (shouldn't be because idx_city None), but ensure not
            if idx_city is not None and idx_fred is None:
                possible = []
                for pos in [idx_city - 2, idx_city + 2]:
                    if 0 <= pos < 5:
                        c = houses[pos]['child']
                        if c is None or c == 'Fred':
                            possible.append(pos)
                if not possible:
                    return False

        # All-different checks (redundant but safe)
        for attr in ['Name', 'vacation', 'child', 'nationality']:
            vals = [houses[i][attr] for i in range(5) if houses[i][attr] is not None]
            if len(vals) != len(set(vals)):
                return False

        return True

    def get_domain(i, attr):
        # Base domain
        if attr == 'Name':
            domain = [v for v in names if v not in used['Name']]
            # Clue 8: Eric not in fifth house
            if i == 4:
                domain = [v for v in domain if v != 'Eric']
            # Mapping constraints with current known attributes
            nat = houses[i]['nationality']
            vac = houses[i]['vacation']
            # If nationality is norwegian -> name must be Peter
            if nat == 'norwegian':
                domain = [v for v in domain if v == 'Peter']
            else:
                # If trying to assign Peter but nationality known and not norwegian
                if nat is not None and nat != 'norwegian':
                    domain = [v for v in domain if v != 'Peter']
            # If nationality is brit -> name must be Alice
            if nat == 'brit':
                domain = [v for v in domain if v == 'Alice']
            else:
                if nat is not None and nat != 'brit':
                    # If nat is non-brit, Alice still allowed but will be caught later; leave domain
                    pass
            # If vacation is camping -> name must be Bob
            if vac == 'camping':
                domain = [v for v in domain if v == 'Bob']
            else:
                if vac is not None and vac != 'camping':
                    domain = [v for v in domain if v != 'Bob']
            return domain

        if attr == 'vacation':
            domain = [v for v in vacations if v not in used['vacation']]
            # Pre-set: house 1 is cruise
            if i == 0:
                domain = ['cruise'] if 'cruise' in domain else []
            # Camping not in house 5
            if i == 4 and 'camping' in domain:
                domain.remove('camping')
            # Name Bob means camping
            name = houses[i]['Name']
            if name == 'Bob':
                domain = [v for v in domain if v == 'camping']
            elif name is not None and name != 'Bob':
                if 'camping' in domain:
                    # If Bob already used elsewhere, camping cannot be here
                    if 'Bob' in used['Name']:
                        domain = [v for v in domain if v != 'camping']
            # Beach to left of Samantha
            # If beach here, must have i<4 and child at i+1 is Samantha or None
            if 'beach' in domain:
                if i == 4:
                    domain.remove('beach')
                else:
                    right_child = houses[i+1]['child']
                    if right_child is not None and right_child != 'Samantha':
                        domain.remove('beach')
                    else:
                        # If Samantha assigned elsewhere not at i+1 -> cannot be beach here
                        sidx = find_index('child', 'Samantha')
                        if sidx is not None and sidx != i+1:
                            if 'beach' in domain:
                                domain.remove('beach')
            # City must be 2 away from Fred
            if 'city' in domain:
                idx_fred = find_index('child', 'Fred')
                if idx_fred is not None:
                    if abs(idx_fred - i) != 2:
                        domain.remove('city')
                else:
                    # Ensure at least one possible spot for Fred at i±2
                    possible = []
                    for pos in [i-2, i+2]:
                        if 0 <= pos < 5:
                            c = houses[pos]['child']
                            if c is None or c == 'Fred':
                                possible.append(pos)
                    if not possible:
                        if 'city' in domain:
                            domain.remove('city')
            return domain

        if attr == 'child':
            domain = [v for v in children if v not in used['child']]
            # Pre-set: house 4 is Meredith
            if i == 3:
                domain = ['Meredith'] if 'Meredith' in domain else []
            # Bella not in house 2
            if i == 1 and 'Bella' in domain:
                domain.remove('Bella')
            # Nationality swede <-> Bella
            nat = houses[i]['nationality']
            if nat == 'swede':
                domain = [v for v in domain if v == 'Bella']
            else:
                if nat is not None and nat != 'swede':
                    # If nat not swede, cannot be Bella if swede assigned elsewhere
                    pass
            # Samantha adjacency with beach to the left
            if 'Samantha' in domain:
                if i == 0:
                    domain.remove('Samantha')
                else:
                    left_v = houses[i-1]['vacation']
                    if left_v is not None and left_v != 'beach':
                        domain.remove('Samantha')
                    else:
                        bidx = find_index('vacation', 'beach')
                        if bidx is not None and bidx != i-1:
                            if 'Samantha' in domain:
                                domain.remove('Samantha')
            # Fred and City distance 2
            if 'Fred' in domain:
                idx_city = find_index('vacation', 'city')
                if idx_city is not None:
                    if abs(idx_city - i) != 2:
                        domain.remove('Fred')
                else:
                    # Ensure there exists a place for city at i±2
                    possible = []
                    for pos in [i-2, i+2]:
                        if 0 <= pos < 5:
                            v = houses[pos]['vacation']
                            if v is None or v == 'city':
                                possible.append(pos)
                    if not possible:
                        if 'Fred' in domain:
                            domain.remove('Fred')
            return domain

        if attr == 'nationality':
            domain = [v for v in nationalities if v not in used['nationality']]
            # Pre-set: house 5 is dane
            if i == 4:
                domain = ['dane'] if 'dane' in domain else []
                return domain
            name = houses[i]['Name']
            child = houses[i]['child']
            # Norwegian <-> Peter
            if name == 'Peter':
                domain = [v for v in domain if v == 'norwegian']
            else:
                if name is not None and name != 'Peter':
                    if 'norwegian' in domain and 'Peter' in used['Name']:
                        # Peter already used elsewhere; cannot be norwegian here
                        domain = [v for v in domain if v != 'norwegian']
            # Brit <-> Alice
            if name == 'Alice':
                domain = [v for v in domain if v == 'brit']
            else:
                if name is not None and name != 'Alice':
                    if 'brit' in domain and 'Alice' in used['Name']:
                        domain = [v for v in domain if v != 'brit']
            # Swede <-> Bella
            if child == 'Bella':
                domain = [v for v in domain if v == 'swede']
            else:
                if child is not None and child != 'Bella':
                    # cannot be swede if Bella used elsewhere
                    if 'swede' in domain and 'Bella' in used['child']:
                        domain = [v for v in domain if v != 'swede']
            # Relative position of swede > norwegian (basic pruning)
            idx_nor = find_index('nationality', 'norwegian')
            idx_swe = find_index('nationality', 'swede')
            # If assigning swede here, ensure norwegian can be to the left
            if 'swede' in domain:
                if idx_nor is not None:
                    if not (i > idx_nor):
                        domain = [v for v in domain if v != 'swede']
                else:
                    # If Peter assigned at p, norwegian must be at p
                    pidx = find_index('Name', 'Peter')
                    if pidx is not None and not (i > pidx):
                        domain = [v for v in domain if v != 'swede']
            # If assigning norwegian here, ensure there's a spot to the right for swede
            if 'norwegian' in domain:
                # cannot be at position 4 because no room right (since 5 is dane)
                if i == 4 or i == 3:
                    domain = [v for v in domain if v != 'norwegian']
                else:
                    if idx_swe is not None:
                        if not (idx_swe > i):
                            domain = [v for v in domain if v != 'norwegian']
            return domain

        return []

    def select_unassigned():
        best = None
        best_domain = None
        for i in range(5):
            for attr in attrs:
                if houses[i][attr] is None:
                    domain = get_domain(i, attr)
                    if best is None or len(domain) < len(best_domain):
                        best = (i, attr)
                        best_domain = domain
                        if len(best_domain) == 0:
                            return best, best_domain
        return best, best_domain

    solution = []

    def backtrack():
        if not consistent():
            return False
        # Check if complete
        complete = True
        for i in range(5):
            for attr in attrs:
                if houses[i][attr] is None:
                    complete = False
                    break
            if not complete:
                break
        if complete:
            solution.append([h.copy() for h in houses])
            return True

        (i, attr), domain = select_unassigned()
        if (i, attr) is None:
            return False
        for val in domain:
            # Assign
            houses[i][attr] = val
            used[attr].add(val)
            if consistent():
                if backtrack():
                    return True
            # Undo
            used[attr].remove(val)
            houses[i][attr] = None
        return False

    backtrack()
    if not solution:
        raise RuntimeError("No solution found")

    sol = solution[0]
    header = ["House", "Name", "vacation", "child", "nationality"]
    rows = []
    for i in range(5):
        row = [
            str(sol[i]['House']),
            sol[i]['Name'],
            sol[i]['vacation'],
            sol[i]['child'],
            sol[i]['nationality']
        ]
        rows.append(row)

    print(json.dumps({
        "solution": {
            "header": header,
            "rows": rows
        }
    }, ensure_ascii=False, indent=2))

if __name__ == "__main__":
    solve()
